all_data = part21_data + part22_scans
assert len(all_data) == 550, f"Expected 550, got {len(all_data)}"

for i, rec in enumerate(all_data, 1):
    assert rec["nr_skanu"] == i, f"Scan number mismatch at {i}: {rec['nr_skanu']}"
    if i >= 326:
        t = rec["transkrypcja"]
        assert '...' not in t[10:-10], f"Mid-ellipsis found in scan {i}: {t}"

with open('/home/ubuntu/workspace/Gen/main_data_j17_part22.json', 'w', encoding='utf-8') as f:
    json.dump(all_data, f, ensure_ascii=False, indent=2)

print(f"SUCCESS: main_data_j17_part22.json saved with {len(all_data)} records (0 mid-ellipsis).")
